 let {tipos,evento={},localPadrao=''}:{tipos:{id:number;nome:string;codigo_cc:string}[];evento?:{nome_evento?:string;data?:string;hora_inicio?:string;hora_fim?:string;local_evento?:string;tipo_culto_id?:number;observacao?:string};localPadrao?:string}=$props();
